  "welcome": "Decile al coach quién sos y contra quién jugás (<b>/civ francos</b>, <b>/vs mongoles</b>, <b>/edad feudal</b>) o directamente en la pregunta. <b>F10</b> para escribir desde el juego, <b>Enter</b> envía y te devuelve el foco. <b>/ayuda</b> para ver los comandos.",
  "help": "<b>Comandos</b> (también podés decirlo en la pregunta):\n<b>/civ</b> francos · <b>/vs</b> mongoles · <b>/edad</b> feudal|castillos|imperial · <b>/mapa</b> arabia · <b>/elo</b> 1100 · <b>/nota</b> texto\n<b>/guia</b> abre la guía visual (F6) · <b>/guia francos</b> · <b>/guia arena</b><br><b>/nueva</b> partida nueva (borra todo) · <b>/reset</b> nueva conversación (mantiene el estado)\n<b>/bo</b> scouts → busca builds · <b>/bo 2</b> elige · <b>/n</b> <b>/p</b> paso siguiente/anterior (F8/F7) · <b>/bo off</b>\n<b>/voz</b> on|off · <b>/mal</b> qué estuvo mal (queda en el log) · <b>/full</b> ⇄ <b>/compact</b> · <b>/log</b> abre la carpeta de logs\n<b>/mapas</b> lista los mapas con perfil · <b>/civ?</b> francos muestra el perfil de una civ\n<b>/rivales</b> mongoles, britanos… · <b>/aliados</b> mayas, … (barra 4v4) · <b>/counters</b> tus counters · <b>/repetir</b> vuelve a leer la última respuesta (o 🔊 en cada respuesta) · <b>/partida</b> lee tu partida en curso (si activaste la detección) · <b>/partida usar</b> la carga · <b>/parche</b> busca parches nuevos",
