  "h.p.47": "Cada pregunta al coach hace ~4-6 llamadas a la API (extracción + herramientas + respuesta): 50 pedidos/día ≈ 10 preguntas. Los modelos chicos usan peor las herramientas y se equivocan más que Claude. Fuente: dev.to/tariqnasser (oct-2026). Verificá nombres de modelos y límites en el panel de cada servicio.",
  "h.option.48": "Automático (según la pregunta)",
  "h.option.49": "Español",
  "h.option.50": "English",
  "h.h3.51": "Partida automática (opcional)",
  "h.p.52": "Lee tu partida en curso desde el perfil público de AoE2 (servicio comunitario aoe2companion) y completa civs y mapa. Si no hay partida o está apagado, la app funciona igual: lo que escribas vos siempre manda.",
  "h.span.53": "Detectar mi partida (consulta cada ~90 s mientras la app está visible)",
