  "h.option.64": "Borrar después de 90 días",
  "h.btnClearLogs.65": "Borrar logs ahora",
  "h.p.66": "Qué sale de tu PC: tus preguntas y las notas relevantes van al proveedor de IA que elegiste; el texto de las respuestas va a Microsoft si usás la voz Edge (SAPI es local); tu id de perfil va a aoe2companion sólo si activás la partida automática; al abrir, la app consulta GitHub (datos del juego de aoe2techtree y builds de rtsbuilds, se puede apagar en Datos) y una vez por día ageofempires.com (noticias de parches, se puede apagar en Parches). Nada se envía al autor de la app.",
  "h.h3.67": "Experimental",
  "h.p.68": "Funciones nuevas que todavía no probamos en partidas reales. Apagadas, la app funciona igual que la v0.11.",
  "h.span.69": "Privacidad reforzada: la key no se vuelve a mostrar, no se envía por http:// a servidores públicos, y permite el modo amnésico",
  "h.span.70": "Modo amnésico: no guardar las API keys en disco (hay que pegarlas en cada sesión)",
  "h.span.71": "Caché de prompt: el prompt fijo y el variable van en bloques separados para reutilizar caché (Claude; recomendado, activado)",
  "h.option.72": "Microsoft Edge neural (gratis, online)",
  "h.option.73": "Windows SAPI (offline, robótica)",
  "h.option.74": "Apagada",
  "h.option.75": "Devolver el foco al juego",
  "h.option.76": "Minimizar y volver a mostrar (si lo anterior no funciona)",
  "h.option.77": "No hacer nada",
  "h.option.78": "Español",
  "h.option.79": "English",
  "h.h2.80": "Sancho Panza <span class=\"muted\">· Age of Empires 2 Fan Companion</span>",
  "h.p.81": "Para usar el <b>chat</b> sólo hace falta una cosa: una <b>API key</b> de una IA. Recomendado: Claude (Anthropic), pago por uso: unos US$0,03–0,05 por pregunta (el costo se muestra debajo de cada respuesta).",
  "h.li.82": "Entrá a <a data-url=\"https://console.anthropic.com/settings/keys\">console.anthropic.com → API Keys</a> (creá la cuenta y cargá saldo en Billing; sin saldo la key no funciona).",
  "h.li.83": "Tocá <b>Create Key</b>, copiala (empieza con <code>sk-ant-</code>) y pegala acá:",
  "h.wTest.84": "Guardar y probar",
  "h.p.85": "Sin key igual podés usar: <b>Build orders</b>, la <b>Guía</b> (civs, mapas, counters), los comandos <code>/civ</code> <code>/vs</code> <code>/bo</code>. Otras IAs (algunas gratis) en Ajustes → Cerebro.",
  "h.span.86": "No mostrar más",
