  "chip.advise": "Consejo IA",
  "chip.sheet": "Ficha",
  "help.sheet": "<b>/ficha</b> muestra la ficha de la partida (civs, mapa, counters, builds) · <b>/consejo</b> [pregunta] pide un consejo a la IA a partir de la ficha · <b>/modo</b> local|ficha|libre cambia cómo responde el chat (sin argumento rota entre los tres)",
  "set.answerMode": "Respuestas del chat",
  "mode.ficha": "Ficha + IA",
  "mode.libre": "Coach libre (IA)",
  "set.answerModeHelp": "Local: la ficha con los datos, sin IA (nada sale de tu PC). Ficha + IA: la IA interpreta tu mensaje y podés pedir consejos. Coach libre: respuestas en texto libre con IA. El detalle de cada modo (qué sale de tu PC, costo, riesgos) está en el recuadro.",
  "mode.changed": "Respuestas: {mode}",
  "set.screenTitle": "Lectura de pantalla (OCR, experimental)",
  "set.screenHelp": "Lee la barra de recursos del juego (madera, comida, oro, piedra, aldeanos en cada uno, población, ociosos, edad, reloj) y la usa en la ficha, el consejo y el reloj del build: el paso cargado te dice cuántos aldeanos faltan y el reloj se sincroniza con el del juego. Necesita el juego en «Ventana sin bordes» y la app visible; en Mac, permiso de grabación de pantalla. «Calibrar» busca la barra en tu pantalla; si no la encuentra, marcala a mano.",
  "set.screenRead": "Leer la barra de recursos del juego cada",
  "set.screenCalibrate": "Calibrar (buscar la barra)",
  "set.screenTest": "Leer ahora",
  "screen.reading": "Leyendo la pantalla…",
  "screen.notHud": "No encontré la barra de recursos del juego. ¿Está el juego abierto, en ventana sin bordes, y la barra a la vista? Probá «Calibrar».",
  "screen.calibrated": "Barra encontrada y guardada ({w}×{h} px). Lectura: {line}",
  "screen.macPerm": "macOS: permití «Grabación de pantalla» para Sancho Panza en Ajustes del Sistema → Privacidad y seguridad, y volvé a abrir la app.",
  "screen.noKey": "La lectura de pantalla usa tu API key: pegala en Ajustes → Cerebro.",
