  "set.mode": "Modo",
  "mode.local": "Local (sin IA)",
  "mode.local.info": "<b>Todo pasa en tu PC.</b> La ficha de partida se arma con los datos del juego (árbol tecnológico, perfiles de civ y mapa, counters calculados, builds), tu mensaje se interpreta por palabras clave y la lectura de pantalla usa Tesseract local. <b>Nada sale de tu computadora</b>; no hace falta cuenta ni API key. <b>Límites:</b> no hay consejos en texto libre, y la interpretación entiende frases simples («soy francos vs mayas en arabia», «me tira arqueros»).",
  "mode.ficha.info": "<b>Como Local, pero una IA interpreta tu mensaje</b> (frases largas, ejércitos, restricciones) y podés <b>pedir un consejo</b> a partir de la ficha. <b>Sale de tu PC:</b> el texto de cada mensaje; si elegís la lectura de pantalla por IA, el recorte de la barra de recursos. <b>Costo con Claude:</b> ~US$0,0002 por mensaje interpretado, ~US$0,03–0,05 por consejo, ~US$0,0003 por lectura de pantalla. <b>Riesgos:</b> la IA puede interpretar mal una frase (la ficha muestra lo que entendió y lo corregís con /civ, /vs…); hace falta una API key, que se guarda cifrada en esta PC.",
  "mode.libre.info": "<b>El coach con IA responde en texto libre</b> (resumen de 3 líneas + detalle, leído en voz alta) usando herramientas sobre los datos: counters, perfiles, stats, builds, notas de guías. <b>Sale de tu PC:</b> tus mensajes y las notas relevantes a cada pregunta. <b>Costo con Claude Sonnet:</b> ~US$0,03–0,05 por pregunta, 8–17 s. <b>Riesgos:</b> respuestas más lentas y caras; la IA puede equivocarse en el razonamiento aunque los números salgan siempre de las herramientas; pagás por uso con tu propia key. <b>Ventaja:</b> consejos concretos para tu situación, con la ficha disponible igual (/ficha).",
  "mode.needsKey": "Este modo usa una IA: pegá tu API key abajo (se guarda cifrada en esta PC).",
  "mode.localOn": "Modo local: la IA está apagada y nada sale de tu PC.",
  "mode.showAi": "Configurar la IA igual (para usarla después)",
  "w.pick": "Elegí cómo usarlo (se cambia cuando quieras en Ajustes → Cerebro):",
  "w.local.t": "Local, sin IA",
  "w.local.d": "Ficha de partida, builds, counters, guía y lectura de pantalla, todo en tu PC. Sin cuenta ni key.",
  "w.local.tag": "Recomendado para empezar",
  "w.ficha.t": "Ficha + IA",
  "w.ficha.d": "La IA interpreta tus mensajes y podés pedirle consejos. ~US$0,0002 por mensaje. Necesita API key.",
  "w.libre.t": "Coach libre (IA)",
  "w.libre.d": "Respuestas en texto libre, como un amigo fuerte en Discord. ~US$0,03–0,05 por pregunta. Necesita API key.",
  "w.keyNeeded": "Pegá tu API key de Claude (console.anthropic.com → API Keys; otras IAs en Ajustes → Cerebro):",
  "w.goLocal": "Empezar en modo local",
  "sheet.adviseLocal": "Consejo con IA: elegí «Ficha + IA» o «Coach libre» en Ajustes → Cerebro",
  "sheet.modeLocal": "Modo local: datos del juego, nada sale de tu PC",
  "set.ocrEngine": "Motor de lectura",
  "ocr.local": "Local (Tesseract, en tu PC)",
  "ocr.ai": "IA (modelo de visión de tu proveedor)",
  "set.ocrHelp": "Local: Tesseract lee los números en tu PC (~0,3 s, gratis, nada sale); lee bien los recursos, población, edad y reloj, y a veces se le escapan los números chicos de aldeanos. IA: el recorte de la barra va al modelo de visión de tu proveedor (Claude Haiku: ~US$0,0003 por lectura, unos US$0,07 por hora cada 15 s), más preciso con texto chico.",
  "set.screenManual": "Marcar la barra a mano",
  "screen.manualHint": "Hacé clic en la esquina superior izquierda de la barra de recursos y después abajo a la derecha, pasando el reloj del centro de la pantalla (queda un rectángulo ancho y bajo que incluye la barra y el reloj).",
  "screen.manualNext": "Ahora la esquina inferior derecha.",
  "screen.saved": "Región guardada ({w}×{h} px).",
