  "h.td.42": "per AI Studio",
  "h.td.43": "the free tier may use your prompts",
  "h.td.44": "Mistral",
  "h.td.45": "10 USD/month in credits",
  "h.td.46": "may train on your prompts (can be disabled)",
  "h.p.47": "Each question to the coach makes ~4-6 API calls (extraction + tools + answer): 50 requests/day ≈ 10 questions. Small models use the tools worse and make more mistakes than Claude. Source: dev.to/tariqnasser (Oct 2026). Check model names and limits in each service's dashboard.",
  "h.option.48": "Automatic (based on the question)",
  "h.option.49": "Español",
  "h.option.50": "English",
  "h.h3.51": "Automatic match (optional)",
  "h.p.52": "Reads your current match from your public AoE2 profile (community service aoe2companion) and fills in civs and map. If there is no match or it is off, the app works the same: what you type always wins.",
  "h.span.53": "Detect my match (checks every ~90 s while the app is visible)",
  "h.profileSearch.54": "Search",
  "h.btnMatchNow.55": "Read match now (/match)",
  "h.h3.56": "Patches",
  "h.span.57": "Check for new patches on launch (official news from ageofempires.com, once a day)",
  "h.btnPatchCheck.58": "Check now",
  "h.h3.59": "Privacy",
  "h.span.60": "Conversation history (logs)",
  "h.option.61": "Always keep",
  "h.option.62": "Delete after 7 days",
  "h.option.63": "Delete after 30 days",
  "h.option.64": "Delete after 90 days",
  "h.btnClearLogs.65": "Delete logs now",
  "h.p.66": "What leaves your PC: your questions and the relevant notes go to the AI provider you chose; the answer text goes to Microsoft if you use the Edge voice (SAPI is local); your profile id goes to aoe2companion only if you turn on automatic match; at start the app contacts GitHub (aoe2techtree game data and rtsbuilds builds, can be turned off under Data) and once a day ageofempires.com (patch news, can be turned off under Patches). Nothing is sent to the app's author.",
  "h.h3.67": "Experimental",
  "h.p.68": "New features we have not tested in real games yet. With them off, the app works exactly like v0.11.",
  "h.span.69": "Hardened privacy: the key is never shown again, is not sent over http:// to public servers, and amnesic mode becomes available",
  "h.span.70": "Amnesic mode: do not save API keys to disk (paste them every session)",
  "h.span.71": "Prompt cache: fixed and variable prompt in separate cached blocks (Claude; recommended, on)",
  "h.option.72": "Microsoft Edge neural (free, online)",
  "h.option.73": "Windows SAPI (offline, robotic)",
  "h.option.74": "Off",
  "h.option.75": "Return focus to the game",
  "h.option.76": "Minimize and show again (if the above does not work)",
  "h.option.77": "Do nothing",
  "h.option.78": "Español",
  "h.option.79": "English",
  "h.h2.80": "Sancho Panza <span class=\"muted\">· Age of Empires 2 Fan Companion</span>",
  "h.p.81": "To use the <b>chat</b> you only need one thing: an AI <b>API key</b>. Recommended: Claude (Anthropic), pay per use: about US$0.03–0.05 per question (the cost is shown under every answer).",
  "h.li.82": "Go to <a data-url=\"https://console.anthropic.com/settings/keys\">console.anthropic.com → API Keys</a> (create the account and add credit in Billing; without credit the key does not work).",
  "h.li.83": "Click <b>Create Key</b>, copy it (it starts with <code>sk-ant-</code>) and paste it here:",
  "h.wTest.84": "Save and test",
  "h.p.85": "Without a key you can still use: <b>Build orders</b>, the <b>Guide</b> (civs, maps, counters), the commands <code>/civ</code> <code>/vs</code> <code>/bo</code>. Other AIs (some free) in Settings → Brain.",
  "h.span.86": "Don't show again",
  "h.wSkip.87": "Use without AI for now",
