  "help.sheet": "<b>/sheet</b> shows the match sheet (civs, map, counters, builds) · <b>/advice</b> [question] asks the AI for advice built on the sheet · <b>/mode</b> local|sheet|free changes how the chat answers (no argument cycles through the three)",
