  "mode.ficha": "Sheet + AI",
  "mode.libre": "Free coach (AI)",
  "set.answerModeHelp": "Local: the sheet from the data, no AI (nothing leaves your PC). Sheet + AI: the AI parses your message and you can ask for advice. Free coach: free-text AI answers. Each mode's details (what leaves your PC, cost, risks) are in the box.",
  "mode.changed": "Answers: {mode}",
  "set.screenTitle": "Screen reading (OCR, experimental)",
  "set.screenHelp": "Reads the game's resource bar (wood, food, gold, stone, villagers on each, population, idle villagers, age, clock) and uses it in the sheet, the advice and the build clock: the loaded step tells you how many villagers are missing and the clock syncs with the game's. Needs the game in \"Borderless window\" and the app visible; on Mac, screen-recording permission. \"Calibrate\" finds the bar on your screen; if it cannot, mark it by hand.",
  "set.screenRead": "Read the game's resource bar every",
  "set.screenCalibrate": "Calibrate (find the bar)",
  "set.screenTest": "Read now",
  "screen.reading": "Reading the screen…",
  "screen.notHud": "Could not find the game's resource bar. Is the game open, in borderless window, with the bar in view? Try \"Calibrate\".",
  "screen.calibrated": "Bar found and saved ({w}×{h} px). Reading: {line}",
  "screen.macPerm": "macOS: allow \"Screen Recording\" for Sancho Panza in System Settings → Privacy & Security, then reopen the app.",
