  "sheet.bonus": "Bonus",
  "set.mode": "Mode",
  "mode.local": "Local (no AI)",
  "mode.local.info": "<b>Everything stays on your PC.</b> The match sheet is built from the game data (tech tree, civ and map profiles, computed counters, builds), your message is parsed by keywords and the screen reading uses local Tesseract. <b>Nothing leaves your computer</b>; no account or API key needed. <b>Limits:</b> no free-text advice, and the parser understands simple phrasing (\"I'm franks vs mayans on arabia\", \"they make archers\").",
  "mode.ficha.info": "<b>Like Local, but an AI parses your message</b> (long phrasing, armies, constraints) and you can <b>ask for advice</b> built on the sheet. <b>Leaves your PC:</b> the text of each message; if you pick AI screen reading, the crop of the resource bar. <b>Cost with Claude:</b> ~US$0.0002 per parsed message, ~US$0.03–0.05 per advice, ~US$0.0003 per screen reading. <b>Risks:</b> the AI may misread a phrase (the sheet shows what it understood; fix it with /civ, /vs…); an API key is needed, stored encrypted on this PC.",
  "mode.libre.info": "<b>The AI coach answers in free text</b> (3-line summary + detail, read aloud) using tools over the data: counters, profiles, stats, builds, guide notes. <b>Leaves your PC:</b> your messages and the notes relevant to each question. <b>Cost with Claude Sonnet:</b> ~US$0.03–0.05 per question, 8–17 s. <b>Risks:</b> slower and pricier answers; the AI can reason wrongly even though the numbers always come from the tools; you pay per use with your own key. <b>Advantage:</b> concrete advice for your situation, with the sheet still available (/sheet).",
  "mode.needsKey": "This mode uses an AI: paste your API key below (stored encrypted on this PC).",
  "mode.localOn": "Local mode: the AI is off and nothing leaves your PC.",
  "mode.showAi": "Set up the AI anyway (to use it later)",
  "w.pick": "Choose how to use it (change it any time in Settings → Brain):",
  "w.local.t": "Local, no AI",
  "w.local.d": "Match sheet, builds, counters, guide and screen reading, all on your PC. No account, no key.",
  "w.local.tag": "Recommended to start",
  "w.ficha.t": "Sheet + AI",
  "w.ficha.d": "The AI parses your messages and you can ask it for advice. ~US$0.0002 per message. Needs an API key.",
  "w.libre.t": "Free coach (AI)",
  "w.libre.d": "Free-text answers, like a strong friend on Discord. ~US$0.03–0.05 per question. Needs an API key.",
  "w.keyNeeded": "Paste your Claude API key (console.anthropic.com → API Keys; other AIs in Settings → Brain):",
  "w.goLocal": "Start in local mode",
  "sheet.adviseLocal": "AI advice: pick \"Sheet + AI\" or \"Free coach\" in Settings → Brain",
  "sheet.modeLocal": "Local mode: game data, nothing leaves your PC",
