  "g.h.p.6": "Pick a civ from the list. The Guide also has: Maps (profile and picture of each map), Units & counters (what beats what), Meta by civ (each civ's meta opening per map type, with its builds and guides), Pro tips (summaries by topic: eco, micro, openings…) and Notes (search across all guides).",
