  "welcome": "Sag dem Coach, wer du bist und gegen wen du spielst (<b>/civ franks</b>, <b>/vs mongols</b>, <b>/age feudal</b>), oder schreib es direkt in die Frage. <b>F10</b> zum Schreiben aus dem Spiel, <b>Enter</b> sendet und gibt dir den Fokus zurück. <b>/help</b> zeigt die Befehle.",
  "help": "<b>Befehle</b> (du kannst es auch einfach in die Frage schreiben):\n<b>/civ</b> franks · <b>/vs</b> mongols · <b>/age</b> feudal|castle|imperial · <b>/map</b> arabia · <b>/elo</b> 1100 · <b>/note</b> Text\n<b>/guide</b> öffnet den visuellen Guide (F6) · <b>/guide franks</b> · <b>/guide arena</b><br><b>/new</b> neues Spiel (löscht alles) · <b>/reset</b> neue Unterhaltung (Status bleibt)\n<b>/bo</b> scouts → sucht Builds · <b>/bo 2</b> wählt aus · <b>/n</b> <b>/p</b> nächster/vorheriger Schritt (F8/F7) · <b>/bo off</b>\n<b>/voice</b> on|off · <b>/bad</b> was falsch war (landet im Log) · <b>/full</b> ⇄ <b>/compact</b> · <b>/log</b> öffnet den Log-Ordner\n<b>/maps</b> listet die Maps mit Profil · <b>/civ?</b> franks zeigt das Profil einer Civ\n<b>/enemies</b> mongols, britons… · <b>/allies</b> mayans, … (4v4-Leiste) · <b>/counters</b> deine Counter · <b>/repeat</b> liest die letzte Antwort nochmal vor (🔊) · <b>/match</b> liest deine laufende Partie (wenn die Erkennung aktiv ist) · <b>/match use</b> lädt sie · <b>/patch</b> sucht neue Patches",
  "noBo": "Keine Builds dafür gefunden. Probier /bo scouts, /bo archers, /bo arena, /bo franks…",
