  "h.td.44": "Mistral",
  "h.td.45": "10 USD/Monat an Guthaben",
  "h.td.46": "können mit deinen Prompts trainieren (abschaltbar)",
  "h.p.47": "Jede Frage an den Coach macht ~4-6 API-Aufrufe (Extraktion + Tools + Antwort): 50 Anfragen/Tag ≈ 10 Fragen. Kleine Modelle nutzen die Tools schlechter und irren sich öfter als Claude. Quelle: dev.to/tariqnasser (Okt. 2026). Prüf Modellnamen und Limits im Dashboard des jeweiligen Dienstes.",
  "h.option.48": "Automatisch (je nach Frage)",
  "h.option.49": "Español",
  "h.option.50": "English",
  "h.h3.51": "Automatische Partie (optional)",
  "h.p.52": "Liest deine laufende Partie aus dem öffentlichen AoE2-Profil (Community-Dienst aoe2companion) und ergänzt Civs und Map. Gibt es keine Partie oder ist die Funktion aus, funktioniert die App genauso: Was du schreibst, hat immer Vorrang.",
  "h.span.53": "Meine Partie erkennen (prüft alle ~90 s, solange die App sichtbar ist)",
  "h.profileSearch.54": "Suchen",
  "h.btnMatchNow.55": "Partie jetzt lesen (/match)",
  "h.h3.56": "Patches",
  "h.span.57": "Beim Start nach neuen Patches suchen (offizielle News von ageofempires.com, 1-mal pro Tag)",
  "h.btnPatchCheck.58": "Jetzt suchen",
  "h.h3.59": "Datenschutz",
  "h.span.60": "Gesprächsverlauf (Logs)",
  "h.option.61": "Immer speichern",
  "h.option.62": "Nach 7 Tagen löschen",
  "h.option.63": "Nach 30 Tagen löschen",
  "h.option.64": "Nach 90 Tagen löschen",
  "h.btnClearLogs.65": "Logs jetzt löschen",
  "h.p.66": "Was deinen PC verlässt: deine Fragen und die passenden Notizen gehen an den gewählten KI-Anbieter; der Antworttext geht an Microsoft, wenn du die Edge-Stimme nutzt (SAPI ist lokal); deine Profil-ID geht nur bei aktivierter automatischer Partie an aoe2companion; beim Start fragt die App GitHub ab (Spieldaten von aoe2techtree und Builds von rtsbuilds, abschaltbar unter Daten) und einmal täglich ageofempires.com (Patch-News, abschaltbar unter Patches). An den Autor der App wird nichts gesendet.",
  "h.h3.67": "Experimentell",
  "h.p.68": "Neue Funktionen, die wir noch nicht in echten Partien getestet haben. Ausgeschaltet funktioniert die App genau wie v0.11.",
  "h.span.69": "Verstärkter Datenschutz: Der Key wird nicht mehr angezeigt, nicht per http:// an öffentliche Server gesendet, und der Amnesie-Modus wird verfügbar",
  "h.span.70": "Amnesie-Modus: API-Keys nicht auf der Festplatte speichern (in jeder Sitzung neu einfügen)",
  "h.span.71": "Prompt-Cache: fester und variabler Prompt in getrennten Cache-Blöcken (Claude; empfohlen, an)",
  "h.option.72": "Microsoft Edge neural (gratis, online)",
  "h.option.73": "Windows SAPI (offline, roboterhaft)",
  "h.option.74": "Aus",
  "h.option.75": "Fokus ans Spiel zurückgeben",
  "h.option.76": "Minimieren und wieder anzeigen (falls das Obige nicht klappt)",
  "h.option.77": "Nichts tun",
  "h.option.78": "Español",
  "h.option.79": "English",
  "h.h2.80": "Sancho Panza <span class=\"muted\">· Age of Empires 2 Fan Companion</span>",
  "h.p.81": "Für den <b>Chat</b> braucht es nur eines: einen <b>API-Key</b> einer KI. Empfohlen: Claude (Anthropic), Bezahlung nach Nutzung: etwa 0,03–0,05 US$ pro Frage (die Kosten stehen unter jeder Antwort).",
  "h.li.82": "Geh auf <a data-url=\"https://console.anthropic.com/settings/keys\">console.anthropic.com → API Keys</a> (Konto anlegen und unter Billing Guthaben aufladen; ohne Guthaben funktioniert der Key nicht).",
  "h.li.83": "Klick auf <b>Create Key</b>, kopier ihn (er beginnt mit <code>sk-ant-</code>) und füg ihn hier ein:",
  "h.wTest.84": "Speichern und testen",
  "h.p.85": "Ohne Key kannst du trotzdem nutzen: <b>Build Orders</b>, den <b>Guide</b> (Civs, Maps, Counter), die Befehle <code>/civ</code> <code>/vs</code> <code>/bo</code>. Andere KIs (einige gratis) unter Einstellungen → Gehirn.",
  "h.span.86": "Nicht mehr anzeigen",
  "h.wSkip.87": "Vorerst ohne KI nutzen",
  "t.btnVoice.88": "Stimme (/voice)",
  "t.btnMode.89": "Erweitern / kompakt (/full)",
