  "t.btnGuide.93": "Visueller Guide: Civs, Maps, Einheiten und Counter, Meta, Notizen (F6 / /guide)",
  "t.boReload.94": "Neu laden",
  "t.boPrev.95": "Zurück (F7)",
  "t.boNext.96": "Weiter (F8)",
