  "prov.claude": "Empfohlene und von uns getestete Option: nutzt die Tools des Coaches gut (Counter, Civs, Builds). Bezahlung nach Nutzung: ~0,02-0,05 USD pro Frage mit Sonnet. Der Key wird verschlüsselt auf diesem PC gespeichert.",
  "prov.openai": "Bezahlung nach Nutzung. Trag unter Modell eines ein, das Tools unterstützt (Function Calling); wähl es aus der Liste in deinem Dashboard.",
  "prov.gemini": "<b>Hat einen Gratis-Plan</b> (Limits in AI Studio, keine feste Tabelle). Achtung: Im Gratis-Plan können deine Prompts zur Verbesserung ihrer Produkte genutzt werden.",
  "prov.groq": "<b>Gratis-Plan</b>: ~30 Anfragen/Min und ~1.000/Tag pro Modell (Limit pro Organisation). Reicht für ganze Partien. Sehr schnell.",
  "prov.openrouter": "<b>Gratis-Modelle</b> (enden auf \":free\"): 20 Anfragen/Min und 50/Tag (≈10 Fragen); 1.000/Tag, wenn du 10 USD auflädst. Gratis-Anbieter können die Prompts protokollieren.",
