  "prov.ollama": "<b>Gratis und privat</b>, läuft auf deinem PC (oder einem anderen: http://IP:11434/v1). Das Modell muss Tools unterstützen: qwen2.5 14B+, llama3.1, mistral-nemo oder Hermes 3 (hermes3). Mit Modellen unter ~14B irrt sich der Coach deutlich öfter. Kein Key nötig.",
