  "chip.advise": "KI-Rat",
  "chip.sheet": "Steckbrief",
  "help.sheet": "<b>/sheet</b> zeigt den Steckbrief der Partie (Civs, Karte, Konter, Builds) · <b>/advice</b> [Frage] holt KI-Rat auf Basis des Steckbriefs · <b>/mode</b> local|sheet|free ändert, wie der Chat antwortet (ohne Argument wechselt es reihum)",
  "set.answerMode": "Chat-Antworten",
  "mode.ficha": "Steckbrief + KI",
  "mode.libre": "Freier Coach (KI)",
  "set.answerModeHelp": "Lokal: der Steckbrief aus den Daten, ohne KI (nichts verlässt deinen PC). Steckbrief + KI: die KI liest deine Nachricht und du kannst um Rat fragen. Freier Coach: KI-Antworten in freiem Text. Die Details jedes Modus (was den PC verlässt, Kosten, Risiken) stehen im Kasten.",
  "mode.changed": "Antworten: {mode}",
  "set.screenTitle": "Bildschirm lesen (OCR, experimentell)",
  "set.screenHelp": "Liest die Ressourcenleiste des Spiels (Holz, Nahrung, Gold, Stein, Dorfbewohner je Ressource, Bevölkerung, Untätige, Zeitalter, Uhr) und nutzt sie im Steckbrief, beim Rat und in der Build-Uhr: der geladene Schritt sagt, wie viele Dorfbewohner fehlen, und die Uhr läuft synchron zum Spiel. Braucht das Spiel im „Randlosen Fenster“ und die sichtbare App; auf dem Mac die Bildschirmaufnahme-Berechtigung. „Kalibrieren“ sucht die Leiste auf deinem Bildschirm; findet es sie nicht, markier sie von Hand.",
  "set.screenRead": "Ressourcenleiste des Spiels lesen alle",
  "set.screenCalibrate": "Kalibrieren (Leiste suchen)",
  "set.screenTest": "Jetzt lesen",
  "screen.reading": "Bildschirm wird gelesen…",
  "screen.notHud": "Die Ressourcenleiste des Spiels wurde nicht gefunden. Läuft das Spiel im randlosen Fenster mit sichtbarer Leiste? Versuch „Kalibrieren“.",
  "screen.calibrated": "Leiste gefunden und gespeichert ({w}×{h} px). Lesung: {line}",
  "screen.macPerm": "macOS: erlaube „Bildschirmaufnahme“ für Sancho Panza unter Systemeinstellungen → Datenschutz & Sicherheit und öffne die App neu.",
  "screen.noKey": "Das Bildschirmlesen nutzt deinen API-Key: trag ihn unter Einstellungen → Gehirn ein.",
