  "sheet.bonus": "Bonus",
  "set.mode": "Modus",
  "mode.local": "Lokal (ohne KI)",
  "mode.local.info": "<b>Alles bleibt auf deinem PC.</b> Der Steckbrief entsteht aus den Spieldaten (Techbaum, Civ- und Kartenprofile, berechnete Konter, Builds), deine Nachricht wird per Schlüsselwörtern gelesen und das Bildschirmlesen nutzt lokales Tesseract. <b>Nichts verlässt deinen Rechner</b>; kein Konto, kein API-Key. <b>Grenzen:</b> keine Ratschläge in freiem Text, und der Parser versteht einfache Sätze („ich bin Franken vs Maya auf Arabia“, „er macht Bogenschützen“).",
  "mode.ficha.info": "<b>Wie Lokal, aber eine KI liest deine Nachricht</b> (lange Sätze, Armeen, Einschränkungen) und du kannst <b>um Rat bitten</b>, aufbauend auf dem Steckbrief. <b>Verlässt deinen PC:</b> der Text jeder Nachricht; beim KI-Bildschirmlesen der Ausschnitt der Ressourcenleiste. <b>Kosten mit Claude:</b> ~0,0002 US$ pro gelesener Nachricht, ~0,03–0,05 US$ pro Rat, ~0,0003 US$ pro Bildschirmlesung. <b>Risiken:</b> die KI kann einen Satz falsch verstehen (der Steckbrief zeigt, was sie verstanden hat; korrigierbar mit /civ, /vs…); ein API-Key ist nötig, verschlüsselt auf diesem PC gespeichert.",
  "mode.libre.info": "<b>Der KI-Coach antwortet in freiem Text</b> (3-Zeilen-Zusammenfassung + Details, vorgelesen) mit Werkzeugen über den Daten: Konter, Profile, Stats, Builds, Guide-Notizen. <b>Verlässt deinen PC:</b> deine Nachrichten und die zur Frage passenden Notizen. <b>Kosten mit Claude Sonnet:</b> ~0,03–0,05 US$ pro Frage, 8–17 s. <b>Risiken:</b> langsamer und teurer; die KI kann sich im Schließen irren, auch wenn die Zahlen immer aus den Werkzeugen kommen; du zahlst pro Nutzung mit deinem eigenen Key. <b>Vorteil:</b> konkreter Rat für deine Lage, der Steckbrief bleibt verfügbar (/sheet).",
  "mode.needsKey": "Dieser Modus nutzt eine KI: trag unten deinen API-Key ein (verschlüsselt auf diesem PC gespeichert).",
  "mode.localOn": "Lokaler Modus: die KI ist aus, nichts verlässt deinen PC.",
  "mode.showAi": "KI trotzdem einrichten (für später)",
  "w.pick": "Wähl, wie du es nutzen willst (jederzeit änderbar unter Einstellungen → Gehirn):",
  "w.local.t": "Lokal, ohne KI",
  "w.local.d": "Steckbrief, Builds, Konter, Guide und Bildschirmlesen, alles auf deinem PC. Kein Konto, kein Key.",
  "w.local.tag": "Zum Einstieg empfohlen",
  "w.ficha.t": "Steckbrief + KI",
  "w.ficha.d": "Die KI liest deine Nachrichten und du kannst sie um Rat fragen. ~0,0002 US$ pro Nachricht. Braucht einen API-Key.",
  "w.libre.t": "Freier Coach (KI)",
  "w.libre.d": "Antworten in freiem Text, wie ein starker Freund auf Discord. ~0,03–0,05 US$ pro Frage. Braucht einen API-Key.",
  "w.keyNeeded": "Trag deinen Claude-API-Key ein (console.anthropic.com → API Keys; andere KIs unter Einstellungen → Gehirn):",
  "w.goLocal": "Im lokalen Modus starten",
  "sheet.adviseLocal": "KI-Rat: wähl „Steckbrief + KI“ oder „Freier Coach“ unter Einstellungen → Gehirn",
  "sheet.modeLocal": "Lokaler Modus: Spieldaten, nichts verlässt deinen PC",
  "set.ocrEngine": "Lese-Engine",
  "ocr.local": "Lokal (Tesseract, auf deinem PC)",
  "ocr.ai": "KI (Vision-Modell deines Anbieters)",
  "set.ocrHelp": "Lokal: Tesseract liest die Zahlen auf deinem PC (~0,3 s, kostenlos, nichts verlässt ihn); Ressourcen, Bevölkerung, Zeitalter und Uhr liest es gut, die kleinen Dorfbewohnerzahlen verfehlt es manchmal. KI: der Ausschnitt der Leiste geht an das Vision-Modell deines Anbieters (Claude Haiku: ~0,0003 US$ pro Lesung, etwa 0,07 US$ pro Stunde bei 15 s), genauer bei kleiner Schrift.",
