  "g.h.p.6": "Wähl eine Civ aus der Liste. Der Guide enthält außerdem: Karten (Profil und Bild jeder Karte), Einheiten & Konter (was schlägt was), Meta je Civ (die Meta-Eröffnung jeder Civ je Kartentyp, mit Builds und Guides), Profi-Tipps (Zusammenfassungen nach Thema: Eco, Micro, Eröffnungen…) und Notizen (Suche in allen Guides).",
