  "welcome": "Diga ao coach quem você é e contra quem joga (<b>/civ franks</b>, <b>/vs mongols</b>, <b>/age feudal</b>) ou direto na pergunta. <b>F10</b> para escrever de dentro do jogo, <b>Enter</b> envia e devolve o foco. <b>/help</b> para ver os comandos.",
  "help": "<b>Comandos</b> (você também pode dizer na pergunta):\n<b>/civ</b> franks · <b>/vs</b> mongols · <b>/age</b> feudal|castle|imperial · <b>/map</b> arabia · <b>/elo</b> 1100 · <b>/note</b> texto\n<b>/guide</b> abre o guia visual (F6) · <b>/guide franks</b> · <b>/guide arena</b><br><b>/new</b> partida nova (apaga tudo) · <b>/reset</b> nova conversa (mantém o estado)\n<b>/bo</b> scouts → busca builds · <b>/bo 2</b> escolhe · <b>/n</b> <b>/p</b> próximo/anterior passo (F8/F7) · <b>/bo off</b>\n<b>/voice</b> on|off · <b>/bad</b> o que deu errado (fica no log) · <b>/full</b> ⇄ <b>/compact</b> · <b>/log</b> abre a pasta de logs\n<b>/maps</b> lista os mapas com perfil · <b>/civ?</b> franks mostra o perfil de uma civ\n<b>/enemies</b> mongols, britons… · <b>/allies</b> mayans, … (barra 4v4) · <b>/counters</b> seus counters · <b>/repeat</b> lê de novo a última resposta (🔊) · <b>/match</b> lê sua partida em andamento (se você ativou a detecção) · <b>/match use</b> carrega ela · <b>/patch</b> busca patches novos",
