  "h.span.26": "URL base",
  "h.span.27": "Chave de API (opcional)",
  "h.summary.28": "Comparativo de APIs grátis (outubro de 2026 — muda com frequência)",
  "h.th.29": "Serviço",
  "h.th.30": "Limite grátis",
  "h.th.31": "Atenção",
  "h.td.32": "Groq",
  "h.td.33": "30 requisições/min · 1.000/dia por modelo",
  "h.td.34": "limite por organização",
  "h.td.35": "OpenRouter",
  "h.td.36": "20/min · 50/dia (1.000/dia com 10 USD carregados)",
  "h.td.37": "podem registrar prompts",
  "h.td.38": "NVIDIA NIM",
  "h.td.39": "40/min · 10.000/dia por modelo",
  "h.td.40": "exige o programa de desenvolvedores",
  "h.td.41": "Google Gemini",
  "h.td.42": "conforme o AI Studio",
  "h.td.43": "o plano grátis pode usar seus prompts",
  "h.td.44": "Mistral",
  "h.td.45": "10 USD/mês em créditos",
  "h.td.46": "podem treinar com seus prompts (dá para desativar)",
  "h.p.47": "Cada pergunta ao coach faz ~4-6 chamadas à API (extração + ferramentas + resposta): 50 requisições/dia ≈ 10 perguntas. Modelos pequenos usam pior as ferramentas e erram mais que o Claude. Fonte: dev.to/tariqnasser (out/2026). Verifique nomes de modelos e limites no painel de cada serviço.",
  "h.option.48": "Automático (conforme a pergunta)",
  "h.option.49": "Español",
  "h.option.50": "English",
  "h.h3.51": "Partida automática (opcional)",
  "h.p.52": "Lê sua partida em andamento a partir do perfil público de AoE2 (serviço comunitário aoe2companion) e preenche civs e mapa. Se não houver partida ou estiver desligado, o app funciona igual: o que você escrever sempre prevalece.",
  "h.span.53": "Detectar minha partida (consulta a cada ~90 s enquanto o app está visível)",
  "h.profileSearch.54": "Buscar",
  "h.btnMatchNow.55": "Ler partida agora (/match)",
  "h.h3.56": "Patches",
  "h.span.57": "Buscar patches novos ao abrir (notícias oficiais de ageofempires.com, 1 vez por dia)",
  "h.btnPatchCheck.58": "Buscar agora",
  "h.h3.59": "Privacidade",
  "h.span.60": "Histórico de conversas (logs)",
  "h.option.61": "Guardar sempre",
  "h.option.62": "Apagar depois de 7 dias",
  "h.option.63": "Apagar depois de 30 dias",
  "h.option.64": "Apagar depois de 90 dias",
  "h.btnClearLogs.65": "Apagar logs agora",
  "h.p.66": "O que sai do seu PC: suas perguntas e as notas relevantes vão para o provedor de IA escolhido; o texto das respostas vai para a Microsoft se usar a voz Edge (SAPI é local); seu id de perfil vai para o aoe2companion só se ativar a partida automática; ao abrir, o app consulta o GitHub (dados do jogo do aoe2techtree e builds do rtsbuilds, pode desligar em Dados) e uma vez por dia o ageofempires.com (notícias de patches, pode desligar em Patches). Nada é enviado ao autor do app.",
  "h.h3.67": "Experimental",
  "h.p.68": "Funções novas que ainda não testamos em partidas reais. Desligadas, o app funciona igual à v0.11.",
  "h.span.69": "Privacidade reforçada: a chave não volta a ser exibida, não é enviada por http:// a servidores públicos e permite o modo amnésico",
  "h.span.70": "Modo amnésico: não salvar as chaves de API no disco (é preciso colá-las a cada sessão)",
  "h.span.71": "Cache de prompt: prompt fixo e variável em blocos separados para reutilizar cache (Claude; recomendado, ativado)",
  "h.option.72": "Microsoft Edge neural (grátis, online)",
  "h.option.73": "Windows SAPI (offline, robótica)",
  "h.option.74": "Desligada",
  "h.option.75": "Devolver o foco ao jogo",
  "h.option.76": "Minimizar e mostrar de novo (se o anterior não funcionar)",
  "h.option.77": "Não fazer nada",
  "h.option.78": "Español",
  "h.option.79": "English",
  "h.h2.80": "Sancho Panza <span class=\"muted\">· Age of Empires 2 Fan Companion</span>",
  "h.p.81": "Para usar o <b>chat</b> só precisa de uma coisa: uma <b>API key</b> de uma IA. Recomendado: Claude (Anthropic), pague pelo uso: cerca de US$ 0,03–0,05 por pergunta (o custo aparece embaixo de cada resposta).",
  "h.li.82": "Entre em <a data-url=\"https://console.anthropic.com/settings/keys\">console.anthropic.com → API Keys</a> (crie a conta e adicione saldo em Billing; sem saldo a chave não funciona).",
  "h.li.83": "Clique em <b>Create Key</b>, copie a chave (começa com <code>sk-ant-</code>) e cole aqui:",
  "h.wTest.84": "Salvar e testar",
  "h.p.85": "Sem chave você ainda pode usar: <b>Build orders</b>, o <b>Guia</b> (civs, mapas, counters), os comandos <code>/civ</code> <code>/vs</code> <code>/bo</code>. Outras IAs (algumas grátis) em Configurações → Cérebro.",
  "h.span.86": "Não mostrar mais",
  "h.wSkip.87": "Usar sem IA por enquanto",
  "t.btnVoice.88": "Voz (/voice)",
  "t.btnMode.89": "Expandir / compactar (/full)",
  "t.btnHide.90": "Ocultar (F9)",
  "t.tbVs.91": "Ver seus counters contra as civs deles (/counters)",
  "t.tbAge.92": "Idade usada para os counters (/age)",
  "t.btnGuide.93": "Guia visual: civs, mapas, unidades e counters, meta, notas (F6 / /guide)",
  "t.boReload.94": "Recarregar",
  "t.boPrev.95": "Anterior (F7)",
  "t.boNext.96": "Próximo (F8)",
