  "chip.sheet": "Ficha",
  "help.sheet": "<b>/sheet</b> mostra a ficha da partida (civs, mapa, counters, builds) · <b>/advice</b> [pergunta] pede um conselho à IA com base na ficha · <b>/mode</b> local|sheet|free muda como o chat responde (sem argumento alterna entre os três)",
  "set.answerMode": "Respostas do chat",
  "mode.ficha": "Ficha + IA",
  "mode.libre": "Coach livre (IA)",
  "set.answerModeHelp": "Local: a ficha com os dados, sem IA (nada sai do seu PC). Ficha + IA: a IA interpreta sua mensagem e você pode pedir conselhos. Coach livre: respostas em texto livre com IA. O detalhe de cada modo (o que sai do PC, custo, riscos) está no quadro.",
  "mode.changed": "Respostas: {mode}",
  "set.screenTitle": "Leitura de tela (OCR, experimental)",
  "set.screenHelp": "Lê a barra de recursos do jogo (madeira, comida, ouro, pedra, aldeões em cada um, população, ociosos, era, relógio) e usa na ficha, no conselho e no relógio do build: o passo carregado diz quantos aldeões faltam e o relógio sincroniza com o do jogo. Precisa do jogo em \"Janela sem bordas\" e do app visível; no Mac, permissão de gravação de tela. \"Calibrar\" procura a barra na sua tela; se não achar, marque à mão.",
  "set.screenRead": "Ler a barra de recursos do jogo a cada",
  "set.screenCalibrate": "Calibrar (achar a barra)",
  "set.screenTest": "Ler agora",
  "screen.reading": "Lendo a tela…",
