  "screen.macPerm": "macOS: permita \"Gravação de tela\" para o Sancho Panza em Ajustes do Sistema → Privacidade e Segurança e reabra o app.",
  "screen.noKey": "A leitura de tela usa sua API key: cole em Ajustes → Cérebro.",
