  "sheet.bonus": "Bônus",
  "set.mode": "Modo",
  "mode.local": "Local (sem IA)",
  "mode.local.info": "<b>Tudo acontece no seu PC.</b> A ficha da partida é montada com os dados do jogo (árvore tecnológica, perfis de civ e mapa, counters calculados, builds), sua mensagem é interpretada por palavras-chave e a leitura de tela usa Tesseract local. <b>Nada sai do seu computador</b>; não precisa de conta nem API key. <b>Limites:</b> não há conselhos em texto livre, e a interpretação entende frases simples (\"sou francos vs maias na arabia\", \"ele faz arqueiros\").",
  "mode.ficha.info": "<b>Como Local, mas uma IA interpreta sua mensagem</b> (frases longas, exércitos, restrições) e você pode <b>pedir um conselho</b> a partir da ficha. <b>Sai do seu PC:</b> o texto de cada mensagem; se escolher a leitura de tela por IA, o recorte da barra de recursos. <b>Custo com Claude:</b> ~US$0,0002 por mensagem interpretada, ~US$0,03–0,05 por conselho, ~US$0,0003 por leitura de tela. <b>Riscos:</b> a IA pode interpretar mal uma frase (a ficha mostra o que entendeu; corrija com /civ, /vs…); precisa de uma API key, guardada cifrada neste PC.",
  "mode.libre.info": "<b>O coach com IA responde em texto livre</b> (resumo de 3 linhas + detalhe, lido em voz alta) usando ferramentas sobre os dados: counters, perfis, stats, builds, notas de guias. <b>Sai do seu PC:</b> suas mensagens e as notas relevantes a cada pergunta. <b>Custo com Claude Sonnet:</b> ~US$0,03–0,05 por pergunta, 8–17 s. <b>Riscos:</b> respostas mais lentas e caras; a IA pode errar no raciocínio mesmo com os números vindo sempre das ferramentas; você paga pelo uso com sua própria key. <b>Vantagem:</b> conselhos concretos para a sua situação, com a ficha disponível do mesmo jeito (/sheet).",
  "mode.needsKey": "Este modo usa uma IA: cole sua API key abaixo (guardada cifrada neste PC).",
  "mode.localOn": "Modo local: a IA está desligada e nada sai do seu PC.",
  "mode.showAi": "Configurar a IA mesmo assim (para usar depois)",
  "w.pick": "Escolha como usar (muda quando quiser em Ajustes → Cérebro):",
  "w.local.t": "Local, sem IA",
  "w.local.d": "Ficha da partida, builds, counters, guia e leitura de tela, tudo no seu PC. Sem conta nem key.",
  "w.local.tag": "Recomendado para começar",
  "w.ficha.t": "Ficha + IA",
  "w.ficha.d": "A IA interpreta suas mensagens e você pode pedir conselhos. ~US$0,0002 por mensagem. Precisa de API key.",
  "w.libre.t": "Coach livre (IA)",
  "w.libre.d": "Respostas em texto livre, como um amigo forte no Discord. ~US$0,03–0,05 por pergunta. Precisa de API key.",
  "w.keyNeeded": "Cole sua API key do Claude (console.anthropic.com → API Keys; outras IAs em Ajustes → Cérebro):",
  "w.goLocal": "Começar no modo local",
  "sheet.adviseLocal": "Conselho com IA: escolha \"Ficha + IA\" ou \"Coach livre\" em Ajustes → Cérebro",
  "sheet.modeLocal": "Modo local: dados do jogo, nada sai do seu PC",
  "set.ocrEngine": "Motor de leitura",
  "ocr.local": "Local (Tesseract, no seu PC)",
  "ocr.ai": "IA (modelo de visão do seu provedor)",
  "set.ocrHelp": "Local: o Tesseract lê os números no seu PC (~0,3 s, grátis, nada sai); lê bem recursos, população, era e relógio, e às vezes perde os números pequenos de aldeões. IA: o recorte da barra vai ao modelo de visão do seu provedor (Claude Haiku: ~US$0,0003 por leitura, uns US$0,07 por hora a cada 15 s), mais preciso com texto pequeno.",
  "set.screenManual": "Marcar a barra à mão",
  "screen.manualHint": "Clique no canto superior esquerdo da barra de recursos e depois embaixo à direita, passando o relógio do centro da tela (fica um retângulo largo e baixo com a barra e o relógio).",
