  "welcome": "告诉教练你是谁、对手是谁（<b>/civ franks</b>、<b>/vs mongols</b>、<b>/age feudal</b>），或直接写在问题里。在游戏中按 <b>F10</b> 输入，<b>Enter</b> 发送并把焦点还给游戏。<b>/help</b> 查看命令。",
  "help": "<b>命令</b>（也可以直接写在问题里）：\n<b>/civ</b> franks · <b>/vs</b> mongols · <b>/age</b> feudal|castle|imperial · <b>/map</b> arabia · <b>/elo</b> 1100 · <b>/note</b> 文本\n<b>/guide</b> 打开图文指南（F6） · <b>/guide franks</b> · <b>/guide arena</b><br><b>/new</b> 新对局（清空全部） · <b>/reset</b> 新对话（保留状态）\n<b>/bo</b> scouts → 搜索开局 · <b>/bo 2</b> 选择 · <b>/n</b> <b>/p</b> 下一步/上一步（F8/F7） · <b>/bo off</b>\n<b>/voice</b> on|off · <b>/bad</b> 标记回答有误（记入日志） · <b>/full</b> ⇄ <b>/compact</b> · <b>/log</b> 打开日志文件夹\n<b>/maps</b> 列出有档案的地图 · <b>/civ?</b> franks 显示某个文明的档案\n<b>/enemies</b> mongols, britons… · <b>/allies</b> mayans, …（4v4 栏） · <b>/counters</b> 你的克制方案 · <b>/repeat</b> 重新朗读上一条回答（🔊） · <b>/match</b> 读取你正在进行的对局（需开启检测） · <b>/match use</b> 载入该对局 · <b>/patch</b> 检查新补丁",
