  "h.p.47": "每次向教练提问会进行约 4-6 次 API 调用（提取 + 工具 + 回答）：50 次请求/天 ≈ 10 个问题。小模型使用工具的能力较差，比 Claude 更容易出错。来源：dev.to/tariqnasser（2026 年 10 月）。请在各服务的控制台核实模型名称和限额。",
