  "h.btnClearLogs.65": "立即删除日志",
  "h.p.66": "哪些数据会离开你的电脑：你的问题和相关笔记会发送给你选择的 AI 提供商；若使用 Edge 语音，回答文本会发送给 Microsoft（SAPI 为本地）；仅在开启自动对局时，你的档案 ID 会发送给 aoe2companion；启动时应用会访问 GitHub（aoe2techtree 游戏数据和 rtsbuilds 建造顺序，可在“数据”中关闭），并每天访问一次 ageofempires.com（补丁新闻，可在“补丁”中关闭）。不会向应用作者发送任何内容。",
  "h.h3.67": "实验性",
  "h.p.68": "尚未在真实对局中测试过的新功能。关闭时，应用与 v0.11 完全相同。",
  "h.span.69": "增强隐私：密钥不再显示，不会通过 http:// 发送到公共服务器，并可启用失忆模式",
  "h.span.70": "失忆模式：不在磁盘上保存 API 密钥（每次会话都需要重新粘贴）",
  "h.span.71": "提示缓存：固定与可变提示分块缓存（Claude；推荐，已开启）",
