  "h.p.81": "使用<b>聊天</b>只需要一样东西：一个 AI 的 <b>API key</b>。推荐 Claude（Anthropic），按用量付费：每个问题约 0.03–0.05 美元（每条回答下方会显示费用）。",
  "h.li.82": "前往 <a data-url=\"https://console.anthropic.com/settings/keys\">console.anthropic.com → API Keys</a>（创建账户并在 Billing 中充值；没有余额密钥无法使用）。",
