  "set.answerModeHelp": "本地：由数据生成对局卡，无 AI（没有数据离开你的电脑）。对局卡 + AI：AI 解析你的消息，可要建议。自由教练：AI 自由文本回答。每个模式的详情（外传内容、费用、风险）见下方说明框。",
