  "set.screenHelp": "读取游戏资源栏（木材、食物、黄金、石料、各资源上的村民数、人口、空闲村民、时代、时钟）并用于对局卡、建议和建造时钟：已载入的步骤会提示还缺多少村民，时钟与游戏同步。需要游戏为“无边框窗口”且应用可见；Mac 需要屏幕录制权限。“校准”在屏幕上查找资源栏；找不到时可手动框选。",
