  "sheet.bonus": "加成",
  "set.mode": "模式",
  "mode.local": "本地（无 AI）",
  "mode.local.info": "<b>一切都在你的电脑上完成。</b>对局卡由游戏数据生成（科技树、文明与地图档案、计算的克制、建造顺序），你的消息按关键词解析，屏幕读取使用本地 Tesseract。<b>没有任何数据离开你的电脑</b>；无需账号或 API 密钥。<b>限制：</b>没有自由文本的建议，解析只理解简单句子（“我是法兰克 vs 玛雅 阿拉伯”、“他出弓箭手”）。",
  "mode.ficha.info": "<b>与本地相同，但由 AI 解析你的消息</b>（长句、军队、限制条件），并可基于对局卡<b>向 AI 要建议</b>。<b>离开你电脑的数据：</b>每条消息的文本；若选择 AI 屏幕读取，还有资源栏的截图。<b>Claude 费用：</b>每条解析消息约 0.0002 美元，每次建议约 0.03–0.05 美元，每次屏幕读取约 0.0003 美元。<b>风险：</b>AI 可能误解句子（对局卡显示它理解的内容，可用 /civ、/vs… 纠正）；需要 API 密钥，加密保存在本机。",
  "mode.libre.info": "<b>AI 教练以自由文本回答</b>（3 行摘要 + 细节，可朗读），通过工具调用数据：克制、档案、数据统计、建造顺序、攻略笔记。<b>离开你电脑的数据：</b>你的消息和与每个问题相关的笔记。<b>Claude Sonnet 费用：</b>每个问题约 0.03–0.05 美元，8–17 秒。<b>风险：</b>回答更慢更贵；即使数字始终来自工具，AI 的推理仍可能出错；用你自己的密钥按量付费。<b>优势：</b>针对你当前局面的具体建议，对局卡仍然可用（/sheet）。",
  "mode.needsKey": "此模式使用 AI：请在下方粘贴 API 密钥（加密保存在本机）。",
  "mode.localOn": "本地模式：AI 已关闭，没有数据离开你的电脑。",
