  "help": "<b>Lệnh</b> (bạn cũng có thể nói thẳng trong câu hỏi):\n<b>/civ</b> franks · <b>/vs</b> mongols · <b>/age</b> feudal|castle|imperial · <b>/map</b> arabia · <b>/elo</b> 1100 · <b>/note</b> nội dung\n<b>/guide</b> mở hướng dẫn trực quan (F6) · <b>/guide franks</b> · <b>/guide arena</b><br><b>/new</b> trận mới (xóa hết) · <b>/reset</b> cuộc trò chuyện mới (giữ trạng thái)\n<b>/bo</b> scouts → tìm build · <b>/bo 2</b> chọn · <b>/n</b> <b>/p</b> bước tiếp/trước (F8/F7) · <b>/bo off</b>\n<b>/voice</b> on|off · <b>/bad</b> chỗ nào sai (ghi vào log) · <b>/full</b> ⇄ <b>/compact</b> · <b>/log</b> mở thư mục log\n<b>/maps</b> liệt kê bản đồ có hồ sơ · <b>/civ?</b> franks xem hồ sơ của một civ\n<b>/enemies</b> mongols, britons… · <b>/allies</b> mayans, … (thanh 4v4) · <b>/counters</b> counter của bạn · <b>/repeat</b> đọc lại câu trả lời cuối (🔊) · <b>/match</b> đọc trận bạn đang chơi (nếu đã bật phát hiện) · <b>/match use</b> nạp trận đó · <b>/patch</b> tìm bản vá mới",
