  "h.h3.56": "Bản vá",
  "h.span.57": "Tìm bản vá mới khi mở ứng dụng (tin chính thức từ ageofempires.com, 1 lần mỗi ngày)",
  "h.btnPatchCheck.58": "Tìm ngay",
  "h.h3.59": "Quyền riêng tư",
  "h.span.60": "Lịch sử trò chuyện (log)",
  "h.option.61": "Luôn lưu",
  "h.option.62": "Xóa sau 7 ngày",
  "h.option.63": "Xóa sau 30 ngày",
  "h.option.64": "Xóa sau 90 ngày",
  "h.btnClearLogs.65": "Xóa log ngay",
  "h.p.66": "Những gì rời khỏi máy bạn: câu hỏi và các ghi chú liên quan được gửi tới nhà cung cấp AI bạn chọn; văn bản câu trả lời được gửi tới Microsoft nếu dùng giọng Edge (SAPI chạy cục bộ); id hồ sơ chỉ gửi tới aoe2companion khi bật trận đấu tự động; khi mở, ứng dụng truy cập GitHub (dữ liệu game từ aoe2techtree và build từ rtsbuilds, tắt được trong Dữ liệu) và mỗi ngày một lần ageofempires.com (tin bản vá, tắt được trong Bản vá). Không gửi gì cho tác giả ứng dụng.",
  "h.h3.67": "Thử nghiệm",
  "h.p.68": "Tính năng mới chưa được thử trong trận thật. Khi tắt, ứng dụng hoạt động y như v0.11.",
  "h.span.69": "Tăng cường quyền riêng tư: key không hiển thị lại, không gửi qua http:// tới máy chủ công cộng, và cho phép chế độ không lưu",
  "h.span.70": "Chế độ không lưu: không lưu API key xuống ổ đĩa (phải dán lại mỗi phiên)",
  "h.span.71": "Bộ nhớ đệm prompt: phần cố định và phần thay đổi ở các khối cache riêng (Claude; khuyên dùng, đang bật)",
  "h.option.72": "Microsoft Edge neural (miễn phí, online)",
  "h.option.73": "Windows SAPI (offline, giọng máy)",
  "h.option.74": "Tắt",
  "h.option.75": "Trả focus về game",
  "h.option.76": "Thu nhỏ rồi hiện lại (nếu cách trên không hiệu quả)",
  "h.option.77": "Không làm gì",
  "h.option.78": "Español",
  "h.option.79": "English",
  "h.h2.80": "Sancho Panza <span class=\"muted\">· Age of Empires 2 Fan Companion</span>",
  "h.p.81": "Để dùng <b>chat</b> chỉ cần một thứ: một <b>API key</b> của AI. Khuyên dùng Claude (Anthropic), trả theo mức dùng: khoảng 0,03–0,05 USD mỗi câu hỏi (chi phí hiện dưới mỗi câu trả lời).",
  "h.li.82": "Vào <a data-url=\"https://console.anthropic.com/settings/keys\">console.anthropic.com → API Keys</a> (tạo tài khoản và nạp tiền ở Billing; không có số dư thì key không hoạt động).",
  "h.li.83": "Bấm <b>Create Key</b>, sao chép key (bắt đầu bằng <code>sk-ant-</code>) và dán vào đây:",
  "h.wTest.84": "Lưu và kiểm tra",
  "h.p.85": "Không có key bạn vẫn dùng được: <b>Build order</b>, <b>Hướng dẫn</b> (civ, bản đồ, counter), các lệnh <code>/civ</code> <code>/vs</code> <code>/bo</code>. Các AI khác (một số miễn phí) ở Cài đặt → Bộ não.",
  "h.span.86": "Không hiện nữa",
  "h.wSkip.87": "Dùng không có AI trước",
