  "chip.sheet": "Phiếu",
  "help.sheet": "<b>/sheet</b> hiện phiếu trận (civ, bản đồ, khắc chế, build) · <b>/advice</b> [câu hỏi] xin AI lời khuyên dựa trên phiếu · <b>/mode</b> local|sheet|free đổi cách chat trả lời (không có tham số thì xoay vòng cả ba)",
  "set.answerMode": "Câu trả lời của chat",
  "mode.ficha": "Phiếu + AI",
  "mode.libre": "Coach tự do (AI)",
  "set.answerModeHelp": "Cục bộ: phiếu từ dữ liệu, không AI (không gì rời khỏi PC). Phiếu + AI: AI phân tích tin nhắn và bạn có thể xin lời khuyên. Coach tự do: trả lời văn bản tự do bằng AI. Chi tiết mỗi chế độ (dữ liệu rời PC, chi phí, rủi ro) ở khung bên dưới.",
  "mode.changed": "Câu trả lời: {mode}",
  "set.screenTitle": "Đọc màn hình (OCR, thử nghiệm)",
  "set.screenHelp": "Đọc thanh tài nguyên của game (gỗ, thức ăn, vàng, đá, dân trên từng loại, dân số, dân rảnh, thời đại, đồng hồ) và dùng cho phiếu, lời khuyên và đồng hồ build: bước đang nạp cho biết còn thiếu bao nhiêu dân và đồng hồ đồng bộ với game. Cần game ở “Cửa sổ không viền” và ứng dụng hiển thị; trên Mac cần quyền ghi màn hình. “Hiệu chỉnh” tìm thanh trên màn hình; nếu không thấy, đánh dấu thủ công.",
  "set.screenRead": "Đọc thanh tài nguyên của game mỗi",
