  "sheet.bonus": "Bonus",
  "set.mode": "Chế độ",
  "mode.local": "Cục bộ (không AI)",
  "mode.local.info": "<b>Mọi thứ diễn ra trên PC của bạn.</b> Phiếu trận được dựng từ dữ liệu game (cây công nghệ, hồ sơ civ và bản đồ, khắc chế đã tính, build), tin nhắn của bạn được đọc theo từ khóa và đọc màn hình dùng Tesseract cục bộ. <b>Không gì rời khỏi máy của bạn</b>; không cần tài khoản hay API key. <b>Giới hạn:</b> không có lời khuyên văn bản tự do, và bộ phân tích chỉ hiểu câu đơn giản (“tôi là Franks vs Mayans ở Arabia”, “nó ra cung thủ”).",
  "mode.ficha.info": "<b>Như Cục bộ, nhưng AI phân tích tin nhắn của bạn</b> (câu dài, quân đội, ràng buộc) và bạn có thể <b>xin lời khuyên</b> dựa trên phiếu. <b>Rời khỏi PC:</b> văn bản mỗi tin nhắn; nếu chọn đọc màn hình bằng AI, ảnh cắt thanh tài nguyên. <b>Chi phí với Claude:</b> ~0,0002 USD mỗi tin nhắn, ~0,03–0,05 USD mỗi lời khuyên, ~0,0003 USD mỗi lần đọc màn hình. <b>Rủi ro:</b> AI có thể hiểu sai câu (phiếu hiện điều nó hiểu; sửa bằng /civ, /vs…); cần API key, được lưu mã hóa trên PC này.",
  "mode.libre.info": "<b>Coach AI trả lời bằng văn bản tự do</b> (tóm tắt 3 dòng + chi tiết, đọc to) dùng công cụ trên dữ liệu: khắc chế, hồ sơ, chỉ số, build, ghi chú hướng dẫn. <b>Rời khỏi PC:</b> tin nhắn của bạn và các ghi chú liên quan đến từng câu hỏi. <b>Chi phí với Claude Sonnet:</b> ~0,03–0,05 USD mỗi câu, 8–17 s. <b>Rủi ro:</b> chậm và đắt hơn; AI có thể suy luận sai dù số liệu luôn lấy từ công cụ; bạn trả theo mức dùng bằng key của mình. <b>Ưu điểm:</b> lời khuyên cụ thể cho tình huống của bạn, phiếu vẫn có sẵn (/sheet).",
  "mode.needsKey": "Chế độ này dùng AI: dán API key của bạn bên dưới (lưu mã hóa trên PC này).",
  "mode.localOn": "Chế độ cục bộ: AI đã tắt và không gì rời khỏi PC của bạn.",
  "mode.showAi": "Vẫn cấu hình AI (để dùng sau)",
