  "w.local.t": "Cục bộ, không AI",
  "w.local.d": "Phiếu trận, build, khắc chế, hướng dẫn và đọc màn hình, tất cả trên PC của bạn. Không cần tài khoản hay key.",
  "w.local.tag": "Khuyên dùng để bắt đầu",
  "w.ficha.t": "Phiếu + AI",
  "w.ficha.d": "AI phân tích tin nhắn và bạn có thể xin lời khuyên. ~0,0002 USD mỗi tin nhắn. Cần API key.",
  "w.libre.t": "Coach tự do (AI)",
  "w.libre.d": "Trả lời văn bản tự do, như một người bạn giỏi trên Discord. ~0,03–0,05 USD mỗi câu. Cần API key.",
