  "welcome": "내가 누구이고 누구와 싸우는지 코치에게 알려 주세요 (<b>/civ franks</b>, <b>/vs mongols</b>, <b>/age feudal</b>). 질문에 바로 써도 됩니다. 게임 중 <b>F10</b>으로 입력하고 <b>Enter</b>로 전송하면 포커스가 게임으로 돌아갑니다. <b>/help</b>로 명령어를 볼 수 있습니다.",
  "help": "<b>명령어</b> (질문에 그냥 말해도 됩니다):\n<b>/civ</b> franks · <b>/vs</b> mongols · <b>/age</b> feudal|castle|imperial · <b>/map</b> arabia · <b>/elo</b> 1100 · <b>/note</b> 텍스트\n<b>/guide</b> 비주얼 가이드 열기 (F6) · <b>/guide franks</b> · <b>/guide arena</b><br><b>/new</b> 새 게임 (모두 삭제) · <b>/reset</b> 새 대화 (상태 유지)\n<b>/bo</b> scouts → 빌드 검색 · <b>/bo 2</b> 선택 · <b>/n</b> <b>/p</b> 다음/이전 단계 (F8/F7) · <b>/bo off</b>\n<b>/voice</b> on|off · <b>/bad</b> 잘못된 점 표시 (로그에 남음) · <b>/full</b> ⇄ <b>/compact</b> · <b>/log</b> 로그 폴더 열기\n<b>/maps</b> 프로필이 있는 맵 목록 · <b>/civ?</b> franks 문명 프로필 보기\n<b>/enemies</b> mongols, britons… · <b>/allies</b> mayans, … (4v4 바) · <b>/counters</b> 내 카운터 · <b>/repeat</b> 마지막 답변 다시 읽기 (🔊) · <b>/match</b> 진행 중인 게임 읽기 (감지를 켠 경우) · <b>/match use</b> 게임 불러오기 · <b>/patch</b> 새 패치 확인",
