  "h.option.64": "90일 후 삭제",
  "h.btnClearLogs.65": "지금 로그 삭제",
  "h.p.66": "PC 밖으로 나가는 것: 질문과 관련 노트는 선택한 AI 제공업체로 전송됩니다. Edge 음성을 쓰면 답변 텍스트가 Microsoft로 전송됩니다(SAPI는 로컬). 프로필 ID는 자동 경기를 켠 경우에만 aoe2companion으로 전송됩니다. 시작 시 앱은 GitHub(aoe2techtree 게임 데이터와 rtsbuilds 빌드, 데이터에서 끌 수 있음)에, 하루 한 번 ageofempires.com(패치 뉴스, 패치에서 끌 수 있음)에 접속합니다. 앱 제작자에게는 아무것도 전송되지 않습니다.",
  "h.h3.67": "실험적",
  "h.p.68": "아직 실제 게임에서 테스트하지 않은 새 기능입니다. 꺼 두면 앱은 v0.11과 똑같이 작동합니다.",
  "h.span.69": "강화된 개인정보 보호: 키를 다시 표시하지 않고, http://로 공개 서버에 보내지 않으며, 기억 상실 모드를 쓸 수 있음",
  "h.span.70": "기억 상실 모드: API 키를 디스크에 저장하지 않음 (세션마다 다시 붙여넣어야 함)",
  "h.span.71": "프롬프트 캐시: 고정 부분과 가변 부분을 별도 캐시 블록으로 (Claude; 권장, 켜짐)",
  "h.option.72": "Microsoft Edge 뉴럴 (무료, 온라인)",
  "h.option.73": "Windows SAPI (오프라인, 기계음)",
  "h.option.74": "끔",
  "h.option.75": "게임으로 포커스 돌려주기",
  "h.option.76": "최소화 후 다시 표시 (위 방법이 안 될 때)",
  "h.option.77": "아무것도 안 함",
  "h.option.78": "Español",
  "h.option.79": "English",
  "h.h2.80": "Sancho Panza <span class=\"muted\">· Age of Empires 2 Fan Companion</span>",
  "h.p.81": "<b>채팅</b>을 쓰려면 AI <b>API 키</b> 하나만 있으면 됩니다. 추천: Claude(Anthropic), 사용량 과금: 질문당 약 US$0.03–0.05 (비용은 각 답변 아래에 표시됩니다).",
  "h.li.82": "<a data-url=\"https://console.anthropic.com/settings/keys\">console.anthropic.com → API Keys</a>에 접속하세요 (계정을 만들고 Billing에서 잔액을 충전하세요. 잔액이 없으면 키가 작동하지 않습니다).",
  "h.li.83": "<b>Create Key</b>를 누르고 키를 복사해서 (<code>sk-ant-</code>로 시작) 여기에 붙여넣으세요:",
  "h.wTest.84": "저장하고 테스트",
  "h.p.85": "키가 없어도 사용할 수 있는 것: <b>빌드 오더</b>, <b>가이드</b> (문명, 맵, 카운터), 명령어 <code>/civ</code> <code>/vs</code> <code>/bo</code>. 다른 AI(일부 무료)는 설정 → 두뇌에서 고를 수 있습니다.",
  "h.span.86": "다시 보지 않기",
  "h.wSkip.87": "지금은 AI 없이 사용",
  "t.btnVoice.88": "음성 (/voice)",
  "t.btnMode.89": "확장 / 축소 (/full)",
  "t.btnHide.90": "숨기기 (F9)",
  "t.tbVs.91": "상대 문명에 대한 내 카운터 보기 (/counters)",
  "t.tbAge.92": "카운터 계산에 쓰는 시대 (/age)",
  "t.btnGuide.93": "비주얼 가이드: 문명, 맵, 유닛과 카운터, 메타, 노트 (F6 / /guide)",
  "t.boReload.94": "새로고침",
