  "prov.claude": "추천하며 저희가 테스트한 옵션: 코치의 도구(카운터, 문명, 빌드)를 잘 활용합니다. 사용한 만큼 결제: Sonnet 기준 질문당 ~0.02-0.05 USD. 키는 이 PC에 암호화되어 저장됩니다.",
  "prov.openai": "사용한 만큼 결제. 모델에는 도구(function calling)를 지원하는 모델을 입력하세요. 대시보드 목록에서 고르면 됩니다.",
  "prov.gemini": "<b>무료 플랜 있음</b> (한도는 AI Studio에서 확인, 고정된 표 없음). 주의: 무료 플랜에서는 프롬프트가 제품 개선에 사용될 수 있습니다.",
  "prov.groq": "<b>무료 플랜</b>: 모델당 분당 ~30회, 하루 ~1,000회 (조직 단위 한도). 게임 한 판 전체에 충분합니다. 매우 빠름.",
  "prov.openrouter": "<b>무료 모델</b> (\":free\"로 끝남): 분당 20회, 하루 50회 (≈질문 10개); 10 USD 충전 시 하루 1,000회. 무료 제공자는 프롬프트를 기록할 수 있습니다.",
  "prov.nvidia": "<b>무료 플랜</b>: 모델당 분당 ~40회, 하루 10,000회. NVIDIA 개발자 프로그램 회원이어야 합니다.",
  "prov.ollama": "<b>무료이고 비공개</b>, 내 PC에서 실행됩니다 (또는 다른 PC: http://IP:11434/v1). 모델이 도구를 지원해야 합니다: qwen2.5 14B+, llama3.1, mistral-nemo 또는 Hermes 3 (hermes3). ~14B 미만 모델에서는 코치가 훨씬 더 자주 틀립니다. 키 불필요.",
  "prov.custom": "OpenAI 형식(/chat/completions)을 쓰고 도구를 지원하는 모든 서비스나 자체 에이전트. Base URL, 모델, 키를 입력하세요.",
