  "help.sheet": "<b>/sheet</b> 경기 카드 표시 (문명, 맵, 카운터, 빌드) · <b>/advice</b> [질문] 카드를 바탕으로 AI 조언 요청 · <b>/mode</b> local|sheet|free 채팅 답변 방식 변경 (인수 없이 쓰면 세 가지를 순환)",
