  "set.answerModeHelp": "로컬: 데이터로 만든 카드, AI 없음 (PC 밖으로 나가는 것 없음). 카드 + AI: AI가 메시지를 해석하고 조언 요청 가능. 자유 코치: AI 자유 텍스트 답변. 각 모드의 상세(외부 전송 내용, 비용, 위험)는 아래 상자에 있습니다.",
  "mode.changed": "답변: {mode}",
  "set.screenTitle": "화면 읽기 (OCR, 실험적)",
  "set.screenHelp": "게임의 자원 바(목재, 식량, 금, 석재, 각 자원의 주민 수, 인구, 유휴 주민, 시대, 시계)를 읽어 카드, 조언, 빌드 시계에 사용합니다: 불러온 단계가 부족한 주민 수를 알려 주고 시계는 게임과 동기화됩니다. 게임은 '테두리 없는 창', 앱은 보이는 상태여야 하며 Mac에서는 화면 녹화 권한이 필요합니다. '보정'이 화면에서 바를 찾고, 못 찾으면 직접 표시하세요.",
