  "sheet.bonus": "보너스",
  "set.mode": "모드",
  "mode.local": "로컬 (AI 없음)",
  "mode.local.info": "<b>모든 것이 내 PC에서 처리됩니다.</b> 경기 카드는 게임 데이터(테크 트리, 문명·맵 프로필, 계산된 카운터, 빌드)로 만들어지고, 메시지는 키워드로 해석되며 화면 읽기는 로컬 Tesseract를 사용합니다. <b>어떤 데이터도 컴퓨터 밖으로 나가지 않습니다</b>; 계정이나 API 키가 필요 없습니다. <b>한계:</b> 자유 텍스트 조언이 없고, 해석은 간단한 문장만 이해합니다 (\"나는 프랑크 vs 마야, 아라비아\", \"상대가 궁수를 뽑아\").",
  "mode.ficha.info": "<b>로컬과 같지만 AI가 메시지를 해석합니다</b> (긴 문장, 군대, 제약) 그리고 카드를 바탕으로 <b>조언을 요청</b>할 수 있습니다. <b>PC 밖으로 나가는 것:</b> 각 메시지의 텍스트; AI 화면 읽기를 선택하면 자원 바의 잘라낸 이미지. <b>Claude 비용:</b> 메시지 해석 1건 약 US$0.0002, 조언 1건 약 US$0.03–0.05, 화면 읽기 1회 약 US$0.0003. <b>위험:</b> AI가 문장을 잘못 해석할 수 있음 (카드가 해석 결과를 보여 주며 /civ, /vs…로 수정); API 키가 필요하며 이 PC에 암호화되어 저장됩니다.",
  "mode.libre.info": "<b>AI 코치가 자유 텍스트로 답합니다</b> (3줄 요약 + 상세, 음성 낭독) — 데이터 위의 도구 사용: 카운터, 프로필, 통계, 빌드, 가이드 노트. <b>PC 밖으로 나가는 것:</b> 내 메시지와 각 질문에 관련된 노트. <b>Claude Sonnet 비용:</b> 질문당 약 US$0.03–0.05, 8–17초. <b>위험:</b> 더 느리고 비쌈; 숫자는 항상 도구에서 오지만 AI의 추론은 틀릴 수 있음; 내 키로 사용량만큼 지불. <b>장점:</b> 내 상황에 맞는 구체적 조언, 카드도 그대로 사용 가능 (/sheet).",
  "mode.needsKey": "이 모드는 AI를 사용합니다: 아래에 API 키를 붙여넣으세요 (이 PC에 암호화 저장).",
  "mode.localOn": "로컬 모드: AI가 꺼져 있고 어떤 데이터도 PC 밖으로 나가지 않습니다.",
  "mode.showAi": "그래도 AI 설정하기 (나중에 사용)",
  "w.pick": "사용 방식을 고르세요 (설정 → 두뇌에서 언제든 변경):",
  "w.local.t": "로컬, AI 없음",
  "w.local.d": "경기 카드, 빌드, 카운터, 가이드, 화면 읽기 모두 내 PC에서. 계정도 키도 필요 없음.",
  "w.local.tag": "시작용으로 추천",
  "w.ficha.t": "카드 + AI",
  "w.ficha.d": "AI가 메시지를 해석하고 조언을 요청할 수 있음. 메시지당 약 US$0.0002. API 키 필요.",
  "w.libre.t": "자유 코치 (AI)",
  "w.libre.d": "자유 텍스트 답변, 디스코드의 고수 친구처럼. 질문당 약 US$0.03–0.05. API 키 필요.",
