  "set.ocrHelp": "로컬: Tesseract가 내 PC에서 숫자를 읽음 (약 0.3초, 무료, 외부 전송 없음); 자원·인구·시대·시계는 잘 읽고 작은 주민 숫자는 가끔 놓침. AI: 바의 잘라낸 이미지를 제공자의 비전 모델로 전송 (Claude Haiku: 1회 약 US$0.0003, 15초 간격 시 시간당 약 US$0.07), 작은 글씨에 더 정확.",
